// Finite port compiler from exact weighted balanced closure. The remaining
// unmatched counter word is pop^k push^l, with k<=entry depth.
#include <bits/stdc++.h>
using namespace std;struct E{int u,v,k,c;};
int main(int ac,char**av){if(ac<10){cerr<<"UNIT.dat SUMMARY PREFIX NORIG ND INITCLASS CUTOFF W LIMIT\n";return 2;}ifstream f(av[1]);int n,m;f>>n>>m;vector<E>es(m);for(auto&e:es)f>>e.u>>e.v>>e.k>>e.c;ifstream sf(av[2]);int nn;sf>>nn;assert(nn==n);vector<vector<pair<int,int>>>rs(n);vector<vector<int8_t>>rows;for(int u=0;u<n;u++){vector<int8_t>row(n);for(int v=0,w;v<n;v++){sf>>w;row[v]=w;if(w>=0)rs[u].push_back({v,w});}rows.push_back(move(row));}string pre=av[3];int no=stoi(av[4]),nd=stoi(av[5]),ic=stoi(av[6]),L=stoi(av[7]),W=stoi(av[8]);size_t cap=stoull(av[9]);assert(no==4*nd&&W>0);vector<vector<int8_t>>vs;unordered_map<string,int>interns;unordered_map<long long,int>cache;auto intern=[&](vector<int8_t>v){string k((char*)v.data(),v.size());auto it=interns.find(k);if(it!=interns.end())return it->second;int id=vs.size();vs.push_back(move(v));interns.emplace(move(k),id);return id;};auto advance=[&](int id,int kind){long long ck=(long long)id*2+(kind==1);auto it=cache.find(ck);if(it!=cache.end())return it->second;auto v=vs[id];vector<int8_t>tmp(n,-1),out(n,-1);for(auto&e:es)if(e.k==kind&&v[e.u]>=0)tmp[e.v]=max<int>(tmp[e.v],min(4,v[e.u]+e.c));for(int u=0;u<n;u++)if(tmp[u]>=0)for(auto[t,w]:rs[u])out[t]=max<int>(out[t],min(4,tmp[u]+w));int ans=intern(move(out));cache[ck]=ans;return ans;};vector<tuple<int,int,int>>ports;vector<vector<int>>portid(no,vector<int>(W,-1));for(int u=0;u<no;u++)for(int d=0;d<W;d++)if(((L-d-(u/nd))&1)==0){portid[u][d]=ports.size();ports.emplace_back(u/nd,u%nd,d);}vector<tuple<int,int,int>>ans;
for(int u=0;u<no;u++){vector<vector<int>>tab(W,vector<int>(W));tab[0][0]=intern(rows[u]);for(int k=1;k<W;k++)tab[k][0]=advance(tab[k-1][0],-1);for(int k=0;k<W;k++)for(int l=1;l<W;l++)tab[k][l]=advance(tab[k][l-1],1);for(int d=0;d<W;d++)if(portid[u][d]>=0)for(int v=0;v<no;v++)for(int dd=0;dd<W;dd++)if(portid[v][dd]>=0){int w=-1;for(int k=0;k<=d;k++){int l=dd-d+k;if(l>=0&&l<W)w=max<int>(w,vs[tab[k][l]][v]);}if(w>=0)ans.emplace_back(portid[u][d],portid[v][dd],w);}if(vs.size()>=cap){cout<<"status CAP vectors "<<vs.size()<<" controls "<<u<<"\n";return 0;}if(u%100==0)cerr<<"controls "<<u<<" vectors "<<vs.size()<<" edges "<<ans.size()<<"\n";}
vector<int8_t>ini(n,-1);for(int h=0;h<4;h++)for(int v=0;v<n;v++)ini[v]=max(ini[v],rows[h*nd+ic][v]);int iid=intern(ini);size_t iters=0;while(true){int p=advance(iid,-1);auto old=vs[iid],next=vs[p];for(int v=0;v<n;v++)next[v]=max(next[v],old[v]);int id=intern(next);iters++;if(id==iid)break;iid=id;}vector<int>initial;vector<int8_t>pref=vs[iid];for(int d=0;d<W;d++){if(d){iid=advance(iid,1);for(int v=0;v<n;v++)pref[v]=max(pref[v],vs[iid][v]);}for(int u=0;u<no;u++)if(portid[u][d]>=0&&pref[u]>=0)initial.push_back(portid[u][d]);}
ofstream out(pre+".ports");out<<ports.size()<<" "<<ans.size()<<" "<<initial.size()<<"\n";for(int p:initial)out<<p<<" ";out<<"\n";for(auto[h,d,z]:ports)out<<h<<" "<<d<<" "<<z<<"\n";for(auto[u,v,w]:ans)out<<u<<" "<<v<<" "<<w<<"\n";cout<<"status COMPILED ports "<<ports.size()<<" summary_edges "<<ans.size()<<" initial_low_ports "<<initial.size()<<" interned_vectors "<<vs.size()<<" prefix_iterations "<<iters<<"\n";
}
